    },
    {
      "module": "vision",
      "passage_id": "PASS-4621b2e17806a7f42c0c6b4e",
      "fact_fields": ["vision.diplopia.present"],
      "licence_pathway": "both",
      "finding": "established_restriction",
      "conclusion": "The guideline requires referral for assessment and implies a temporary no-driving status pending investigation, as the patient is currently unfit."
